190	 */
191	export function selectWedgeReapCandidates(
192	  output: ReadonlyMap<string, { at: number }>,
193	  tracked: ReadonlySet<string>,
194	  inFlight: ReadonlySet<string>,
195	  now: number,
196	  silentMs: number = WEDGE_REAP_SILENT_MS,
197	): string[] {
198	  const out: string[] = [];
199	  for (const [id, e] of output) {
200	    if (tracked.has(id) && !inFlight.has(id) && e.at > 0 && now - e.at > silentMs) out.push(id);
201	  }
202	  return out;
203	}
