253	/**
254	 * Heartbeat loop (P-011): while this host has live spawns, bump their
255	 * `heartbeat_at` every SPAWN_HEARTBEAT_INTERVAL_MS so the reclaim sweep can tell
256	 * a live spawn from one whose host died. Lazily started on the first spawn and
257	 * self-stopping when the last local spawn finishes. `unref`'d so it never holds
258	 * the process open. The same tick stamps `last_output_at` for spawns whose
259	 * stream moved since the last persist (P-008 — zero extra write cadence).
260	 */
261	let heartbeatTimer: ReturnType<typeof setInterval> | null = null;
262	function ensureSpawnHeartbeatLoop(): void {
263	  if (heartbeatTimer) return;
264	  heartbeatTimer = setInterval(() => {
265	    const ids = [...localSpawnAborts.keys()];
266	    if (ids.length === 0) {
267	      if (heartbeatTimer) clearInterval(heartbeatTimer);
268	      heartbeatTimer = null;
269	      return;
270	    }
271	    const outputAt = new Map<string, number>();
272	    for (const id of ids) {
273	      const e = localSpawnOutput.get(id);
274	      if (e && e.at > e.persistedAt) {
275	        outputAt.set(id, e.at);
276	        e.persistedAt = e.at;
277	      }
278	    }
279	    void heartbeatSpawns(getOrgPg().sql, ids, outputAt).catch(() => {
280	      /* best-effort — a missed beat at worst risks an early reclaim, which is
281	         itself recoverable (an autonomous spawn re-runs; an interactive one is
282	         the human's to relaunch). */
283	    });
284	    // P-010/D-006: same tick, after the beat — reap local spawns wedged past
285	    // the threshold (flag-gated inside; double-fire guarded).
286	    void reapWedgedLocalSpawns(Date.now()).catch(() => {
287	      /* best-effort — a failed reap retries next tick */
288	    });
289	  }, SPAWN_HEARTBEAT_INTERVAL_MS);
290	  if (typeof heartbeatTimer.unref === 'function') heartbeatTimer.unref();
