385	 * reclaim-then-count-then-insert sequence had under read-committed:
386	 *   • two concurrent spawns both read running<cap and both recorded
387	 *     (ceiling overshoot, P-039);
388	 *   • a route-timeout retry of the SAME logical spawn launched a second agent
389	 *     (EI-73) — a caller-supplied idempotencyKey now returns the original row
390	 *     instead. The partial unique index from migration 219 backstops the
391	 *     dedupe even outside this lock.
392	 *
393	 * `record` runs inside the transaction only when admission succeeds; it must
394	 * use the handed tx. Exported for the real-PG concurrency tests.
395	 */
396	export async function admitSpawn(
397	  sql: Sql,
398	  opts: {
399	    workspaceId: string;
400	    /** The spawn id `record` inserts — the idempotency key is stamped on it. */
401	    spawnId: string;
402	    idempotencyKey: string | null;
403	    cap: number;
404	    record: (tx: Db) => Promise<void>;
405	  },
406	): Promise<{ admission: SpawnAdmission; reclaimed: { count: number; workspaces: string[] } }> {
407	  let reclaimed = { count: 0, workspaces: [] as string[] };
408	  const admission = (await sql.begin(async (tx): Promise<SpawnAdmission> => {
409	    await tx`SELECT pg_advisory_xact_lock(hashtext(${`opspawn:${opts.workspaceId}`}))`;
410	
