" 2>&1 | head -20

npx tsx -e "
const { getOrgPg } = await import('@papercusp/db-org');
const { sql } = getOrgPg();

const ISSUE_COLS = \`issue_id, kind, scope, title, body, severity, source, state, assignee,
  assigned_by, assigned_at, payload, found_during, linked_feature_id, created_by,
  signal_origin, assignee_rank, rank_writer, rank_updated_at, created_at, updated_at\`;

// Get the issue row
const rows = await sql\`SELECT \${sql.unsafe(ISSUE_COLS)} FROM harness_shared.engineer_issues WHERE issue_id = 'EI-172'\`;
console.log('ISSUE ROW:', JSON.stringify(rows[0], null, 2));

// Get topic tags
const tagRows = await sql\`SELECT dst_ref FROM harness_shared.coord_links WHERE src_kind = 'issue' AND src_ref = 'EI-172' AND rel = 'tagged'\`;
console.log('TOPICS:', JSON.stringify(tagRows, null, 2));

// Get thread posts
const threadRows = await sql\`SELECT * FROM harness_shared.coord_threads WHERE thread_id = 'issue-thread-EI-172'\`;
console.log('THREAD:', JSON.stringify(threadRows, null, 2));

const posts = await sql\`SELECT * FROM harness_shared.coord_thread_posts WHERE thread_id = 'issue-thread-EI-172' ORDER BY created_at ASC\`;
console.log('POSTS:', JSON.stringify(posts, null, 2));

// Get links out (non-tagged)
const linkRows = await sql\`SELECT rel, dst_kind, dst_ref FROM harness_shared.coord_links WHERE src_kind = 'issue' AND src_ref = 'EI-172' AND rel != 'tagged'\`;
console.log('LINKS OUT:', JSON.stringify(linkRows, null, 2));

process.exit(0);
" 2>&1
